validator:
function validate(input) {
  const [{ Spending = [] }] = input;
  const keys = new Set();
  for (const [user, date, platform, amount] of Spending) {
    if (user === null || date === null || platform === null || amount === null) return 'Every column is required.';
    if (platform !== 'desktop' && platform !== 'mobile') return `Unknown platform ${platform}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `spend_date ${date} is not YYYY-MM-DD.`;
    if (amount < 0) return 'amount cannot be negative.';
    const key = `${user}|${date}|${platform}`;
    if (keys.has(key)) return `User ${user} has two ${platform} rows on ${date}.`;
    keys.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const amounts = [10, 25, 50, 100, 100, 250];
  const day = offset => new Date(Date.UTC(2019, 6, 1 + offset)).toISOString().slice(0, 10);
  const users = small ? 1 + pick(4) : 40, days = small ? 1 + pick(3) : 60, rows = small ? pick(9) : 2000;
  const Spending = [], seen = new Set();
  for (let tries = 0; Spending.length < rows && tries < rows * 10; tries++) {
    const user = 1 + pick(users), date = day(pick(days));
    // Half the time a user who spent on one platform that day also spends on the other.
    const platforms = rand() < 0.5 ? ['desktop', 'mobile'] : [rand() < 0.5 ? 'desktop' : 'mobile'];
    for (const platform of platforms) {
      const key = `${user}|${date}|${platform}`;
      if (seen.has(key) || Spending.length >= rows) continue;
      seen.add(key);
      Spending.push([user, date, platform, amounts[pick(amounts.length)]]);
    }
  }
  return [{ Spending }];
}
